import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%80%90%E6%9B%B8%E7%B1%8D%E3%80%91%E8%88%88%E4%BA%A1%E3%81%AE%E4%B8%96%E7%95%8C%E5%8F%B2%E3%80%81%E3%82%B7%E3%83%AB%E3%82%AF%E3%83%AD%E3%83%BC%E3%83%89%E3%81%A8%E5%94%90%E5%B8%9D%E5%9B%BD.html","title":"【書籍】興亡の世界史、シルクロードと唐帝国","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":2.38,"words":714},"filePathRelative":"【書籍】興亡の世界史、シルクロードと唐帝国.md"}`),a={name:`【書籍】興亡の世界史、シルクロードと唐帝国.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="【書籍】興亡の世界史、シルクロードと唐帝国" tabindex="-1"><a class="header-anchor" href="#【書籍】興亡の世界史、シルクロードと唐帝国"><span>【書籍】興亡の世界史、シルクロードと唐帝国</span></a></h1><p><a href="./世界史.html">世界史</a>の<a href="./書籍.html">書籍</a></p><p><a href="https://amzn.to/48NtQ47" target="_blank" rel="noopener noreferrer">amazon: 興亡の世界史　シルクロードと唐帝国</a></p><h2 id="興亡の世界史シリーズの雑感" tabindex="-1"><a class="header-anchor" href="#興亡の世界史シリーズの雑感"><span>興亡の世界史シリーズの雑感</span></a></h2><p>興亡の世界史シリーズはこれまでも割と読んでいた。歴史小説的な面白さ、読みやすさと、ちゃんとした歴史の教科書的な、歴史としてある程度信じて良い内容的なもののバランスを求めてこのシリーズを読んでいる訳だが、 シリーズというほど統一感がある訳でも無く巻によってだいぶ歴史小説側だったり歴史の教科書側だったりする。 また、当たり外れも結構あって、何も面白くないものととても良く書けているものがある。</p><p>タイトルからあるように、興亡という視点がちょうどマッチする対象は良く書けていて、興亡というわかりやすさの無い時代、地域では冴えないという印象。イスラム帝国のジハードなどは良く書けていた。</p><h2 id="読み始め-2026-05-10-日" tabindex="-1"><a class="header-anchor" href="#読み始め-2026-05-10-日"><span>読み始め 2026-05-10 (日)</span></a></h2><p>図書館をもう少し活用しようという気分になったので、以前読んでいた興亡の世界史シリーズで読んでない奴を読み始める。選んだのはシルクロードと唐帝国。</p><p>序文はシルクロードも唐も関係なくひたすら民族とか西欧中心的な史観の批判が続き、しかも2026年現代からするともはやそうでも無いような事が多くてげんなりする。歴史の教科書なのにあまり短期的な視点でものを書くと長く残る本では恥を晒すという残念な感じになってしまっている。 アメリカが正しい、みたいな思い込みみたいなのはもはや完全に無くなってしまっているよなぁ。 それはバランス良くものを見るようになったというよりはもっと残念な現状の結果だが。</p><p>一方、グレコローマンから現在の西洋につながってはいない、という認識が自分の感覚としても常識となっているのはこの興亡の世界史のシリーズの影響も結構大きい事を思えば、この著者を含めた歴史研究者が頑張った結果といえるかもしれない。 そうだとするなら、この著者の序文もここ20年で達成出来た事をむしろ誇るべき内容なのかもしれず。</p><p>何にせよ、第一章の最初まで読んだ感じ、第一章からは割とちゃんとしている。序章が全く同意出来なくても問題は無さそう。</p><h3 id="久しぶりの物理本と老眼鏡" tabindex="-1"><a class="header-anchor" href="#久しぶりの物理本と老眼鏡"><span>久しぶりの物理本と老眼鏡</span></a></h3><p>老眼の結果あまり物理本を読まなくなっていたが、今後図書館を使っていくなら老眼鏡をつかって物理本を読んでいこう、と思って試している。 老眼鏡を使えば割と以前の通り読めるな。</p><h2 id="_3章、唐の建国と突厥の興亡-2026-06-06-土" tabindex="-1"><a class="header-anchor" href="#_3章、唐の建国と突厥の興亡-2026-06-06-土"><span>3章、唐の建国と突厥の興亡 2026-06-06 (土)</span></a></h2><p>3章でようやく唐が登場する。そして3章の終わりまでで、唐の全盛期が終わる感じとなる。 唐の歴史をあまり知らなかったが、勉強になった。なかなか面白いし。</p><p>この本は隋の最後くらいから語られるが隋との連続性はかなり強く、 もっと言うと北魏からの連続性がかなり強い。 その辺の話は他の本で補ったりしながら読んでいる。</p><p>自分の印象では中国というのはほとんどの期間で遊牧民にほぼ隷属しているような状況と思っていたが、 唐は突厥を倒したり、割としっかりと優勢だな。 そして唐は割と遊牧民国家だな。 どうみても北魏の系譜だろう。</p><p>ただちゃんと中国側も支配しているので、中国の王朝でもある二面性があったのだろうな。</p><p>それにしてもなんで日本は隋に使者を送っていたのだろうか？ 隋は別段安定していた訳でも凄く強かった訳でも無さそうだが。 北魏ではなく隋に使者を送った理由は何かあるのかな？</p><h2 id="読み終わり、なかなか良かった-2026-08-22-土" tabindex="-1"><a class="header-anchor" href="#読み終わり、なかなか良かった-2026-08-22-土"><span>読み終わり、なかなか良かった 2026-08-22 (土)</span></a></h2><p>日があいたが、無事最後まで読んだ。途中飛ばしたところもあるが、全体としては結構良かった。</p><p>まず序盤と最後に自虐史観がどうだとか欧米の歴史観がどうだとかがいろいろあるのはかなりげんなりすると思うが、 本体の内容はそういうのはあまり関係ないので頑張って耐えて進む事をオススメする。</p><p>自分は唐の話が知りたいな、と思って本書を読み始めたが、唐の歴史書としてはちょっと内容は薄めだった。 一方で唐の周辺の内容はかなり充実している。 突厥とウィグル帝国の話の方が長いのでは？そしてどの章でもソグド人の話してる。</p><p>けれど、そういうシルクロード周辺の話題は、唐という事を知るのにむしろ良かったという気もする内容で、 中央アジアの視点から見るというのはその後の歴史とのつながりを見る上で、なかなか良い視点だなぁ、と説得された。 この辺、著者の中央アジア史の専門家としての知見を一般に伝える事に成功している良著だと思った。</p><p>中央アジアの視点からこの時代を眺める、というのは、全く自分の知らないものだったが、 同シリーズのスキタイから匈奴、イスラム、モンゴル帝国、オスマン・トルコをつなげる大きなピースに感じられた。</p><p>内容はかなり細かく専門的で、いちいち研究者の名前が出てきてそれを否定したり肯定したり、という事が結構多い。 これは素人が単にお話としての歴史を知りたいんだ、と思う時には過剰なのだけれど、 一方で歴史をちゃんと学ぶとこうなるものなので、 導入と最後の主張強そうな内容からは良い意味で期待を裏切られる学問的誠実さを感じる態度で、 とても好印象だった。 しかも門外漢の自分でもついていける程度の記述になっているので、 一般向けに配慮はしているのだろう、という事も分かる。</p><p>ただ唐の歴史を知りたい人からすると随の話がないのはやっぱり突然途中から始まる感じに思えて、 北魏-随-唐の流れは別の本で補う必要はあるとは思った。</p><p>全体としてはかなり満足した。読むに値する本だったと思うし、内容の専門性を思えば頑張って素人にも分かるように書いていると思う。</p>`,28)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};